function payroll_build_month(string $month,array $cfg,?string $company41=null):void {
 $from=$month.'-01';$to=(new DateTimeImmutable($from))->format('Y-m-t');
    foreach(query("SELECT * FROM ep_users WHERE role<>'admin'")->fetchAll()as $staff){
     $GLOBALS['EP_SCREEN']='payroll';$actor=current_user();if($actor['role']!=='admin'&&!in_array((int)$staff['id'],permission_scope29($actor,'payroll','create'),true))continue;$uid2=(int)$staff['id'];$staff=query('SELECT * FROM ep_users WITH (UPDLOCK, HOLDLOCK) WHERE id=?',[$uid2])->fetch();unset($GLOBALS['EP_SERVICE_CACHE'][$uid2],$GLOBALS['EP_SALARY_CACHE'][employee_key($staff)]);$state=service_state($staff,$to);if(!pay41_build_matches($staff,$month,$company41))continue;$visible=false;$during=false;foreach(days_between($from,$to)as $d){$candidate=service_state($staff,$d);if($candidate['employed']){$during=true;if($candidate['payroll'])$visible=true;}}if(!$during)continue;query('SELECT id FROM ep_users WITH (UPDLOCK, HOLDLOCK) WHERE id=?',[$uid2]);if(query("SELECT TOP (1) id FROM ep_payroll WHERE user_id=? AND status='approved' AND month_key>?",[$uid2,$month])->fetch())fail('اعتمد الكشوف بترتيب الشهور؛ يوجد كشف لاحق معتمد.');$old=query('SELECT * FROM ep_payroll WITH (UPDLOCK, HOLDLOCK) WHERE user_id=? AND month_key=?',[$uid2,$month])->fetch();if($old&&in_array($old['status'],['approved','submitted'],true))continue;
     if(historical_for($uid2,'payroll',$month,$month))continue;
     $prepared37=payroll_calculate37($staff,$month,$cfg,$old?:null);$calc=$prepared37['calculation'];$net=$prepared37['net'];
     query("MERGE INTO ep_payroll WITH (HOLDLOCK) AS target USING (VALUES (?, ?, ?, ?, ?)) AS source (user_id, month_key, calculation_json, net_amount, created_at) ON target.user_id=source.user_id AND target.month_key=source.month_key WHEN MATCHED THEN UPDATE SET status='draft',calculation_json=source.calculation_json,net_amount=source.net_amount,created_at=source.created_at WHEN NOT MATCHED THEN INSERT (user_id, month_key, calculation_json, net_amount, created_at) VALUES (source.user_id, source.month_key, source.calculation_json, source.net_amount, source.created_at);",[$uid2,$month,jencode($calc),$net,utc_now()]);
    }
}

function payroll_calculate37(array $staff,string $month,array $cfg,?array $old=null):array {
 $from=$month.'-01';$to=pay35_month($month);$uid2=(int)$staff['id'];$visible=false;foreach(days_between($from,$to)as $date37){$service37=service_state($staff,$date37);if($service37['employed']&&$service37['payroll'])$visible=true;}
     $input35=pay35_inputs($uid2,$month);$basis35=pay35_basis($staff,$month,(float)$input35['extra_days']);$rules35=pay35_rules($to);
     $report=attendance_report($uid2,$from,$to);$days=0.0;$minutes=0;$overtime=0;$flags=[];$deduction=0.0;$addition=0.0;$allowanceDeduction=array_fill_keys(array_keys(allowance_keys()),0.0);$basicDeduction=0.0;$extraUnpaid=[];$lateDays35=0.0;$absenceLoss35=0.0;$sickLoss35=0.0;
     $friday=pay35_fridays($staff,$month);$flags=array_merge($flags,$friday['flags']??[]);$paidDates35=array_column($basis35['segments'],'date');
     foreach($report as $d){
      if(!in_array($d['date'],$paidDates35,true))continue;
      if(!$d['configured']){$flags[]=$d['date'].': دوام غير معتمد';continue;}
      if($d['unclosed_permission'])$flags[]=$d['date'].': إذن غير مغلق';
      $loss=($d['absence']?1:0)+($d['sick_paid']!==null?1-(float)$d['sick_paid']:0)+$d['penalty_days'];$hours=max(0.01,(float)($d['scheduled_hours']??$cfg['work_hours']));$late=($d['late_minutes']+$d['early_minutes']+$d['penalty_minutes']+($d['permission_deduct_minutes39']??0))/$hours/60;
      $days+=$loss;$minutes+=$d['late_minutes']+$d['early_minutes']+$d['penalty_minutes']+($d['permission_deduct_minutes39']??0);$lateDays35+=$late+$d['penalty_days'];$daySalary=salary_at($staff,$d['date']);$wage=$daySalary['fixed_salary']?$daySalary['salary']:0;$dayRate=$wage/26;$a=allowance_at($staff,$d['date']);$fraction=$loss+$late;
      $basicDeduction+=$fraction*$dayRate;foreach($allowanceDeduction as $k=>$v)$allowanceDeduction[$k]+=$fraction*$a[$k]/26;
      $combinedRate35=($wage+array_sum(array_intersect_key($a,array_flip(array_keys(allowance_keys())))))/26;$absenceLoss35+=($d['absence']?1:0)*$combinedRate35;$sickLoss35+=($d['sick_paid']!==null?1-(float)$d['sick_paid']:0)*$combinedRate35;
      // Remaining after scheduled end creates no automatic additional pay (owner policy V199).
     }
     $salarySnapshot=['salary'=>$basis35['salary'],'effective_from'=>$basis35['effective_from'],'segments'=>$basis35['segments'],'rule'=>$basis35['rule']];$monthlySalary=$salarySnapshot['salary'];
     $allowanceSnapshot=['amounts'=>$basis35['allowances'],'segments'=>$basis35['segments'],'total'=>array_sum($basis35['allowances'])];
     $basicDeduction=min($monthlySalary+($basis35['extra_parts']['basic']??0),$basicDeduction);foreach($allowanceDeduction as $k=>$v)$allowanceDeduction[$k]=round(min($allowanceSnapshot['amounts'][$k]+($basis35['extra_parts'][$k]??0),$v),3);
     $attendanceDeduction=round($basicDeduction+array_sum($allowanceDeduction),3);$deduction=$attendanceDeduction;$addition+=$allowanceSnapshot['total']+$friday['amount']+$basis35['extra_amount'];
     $lateRatio35=min(1,$lateDays35/26);$fridayLoss35=0;$deduction+=$fridayLoss35;

     $loanItems=[];$leaveCashItems=[];$penalty35=0.0;
     foreach(query("SELECT * FROM ep_records WHERE user_id=? AND status='approved' AND module IN ('discipline','adjustment','loan','leave_cash')",[$uid2])->fetchAll()as $r){
      $body=decode($r['body_json']);
      if($r['module']==='loan')continue;
      if($r['module']==='leave_cash'&&($body['payment_method']??'bank_salary')!=='bank_salary')continue;if(($body['payroll_month']??'')===$month){if($r['module']==='leave_cash')$leaveCashItems[]=['id'=>(int)$r['id'],'amount'=>(float)$r['amount'],'days'=>(float)$body['days']];if(in_array($r['module'],['adjustment','leave_cash'],true))$addition+=(float)$r['amount'];else{$deduction+=(float)$r['amount'];$penalty35+=(float)$r['amount'];}}
     }
     $addition+=v26_additions_total($uid2,$month);$commission35=pay35_commissions($uid2,$month);$commissionItems=$commission35['items'];$flags=array_merge($flags,$commission35['flags']);foreach($commissionItems as $ci)$addition+=(float)$ci['amount'];$contractGross35=array_sum(array_column(array_filter($commission35['lines'],fn($line)=>$line['type']==='delivery_contract'),'amount'));$contractLoss35=0;$deduction+=$contractLoss35;$commissionDeduction36=(float)$input35['sales_agent_deduction36']+(float)$input35['collection_deduction36'];$deduction+=$commissionDeduction36;$penalty35+=$commissionDeduction36;foreach(['sales_agent'=>'sales_agent_deduction36','collection'=>'collection_deduction36']as $type36=>$field36){$available36=max(0,array_sum(array_column(array_filter($commission35['lines'],fn($l)=>$l['type']===$type36),'amount')));if((float)$input35[$field36]>$available36)$flags[]='خصم العمولة يتجاوز صافي عمولة النوع: '.commission_types()[$type36];}$payDate=$to;foreach(array_reverse(days_between($from,$to))as $d)if(service_state($staff,$d)['employed']){$payDate=$d;break;}$state=service_state($staff,$payDate);$payment=payment_snapshot($staff,$payDate);if(!payout_held($staff)&&!empty($payment['profile']['payment_unconfirmed']))$flags[]='طريقة الاستلام غير محددة';if($payment['method']==='incomplete')$flags[]='بيانات التحويل البنكي ناقصة';if($payment['method']==='bank'&&!$payment['terms_record'])$flags[]='تاريخ سريان بيانات البنك غير مسجل';
     $debtBalance=v28_debt_balance($uid2,$to);$debtChoice=round((float)($old?decode($old['calculation_json'])['debt_deduction']??0:($input35['debt_choice']??0)),3);$debtChoice=min($debtChoice,$debtBalance,max(0,$monthlySalary+$addition-$deduction));$deduction+=$debtChoice;
     $calc=['attendance_version39'=>39,'monthly_grace_version397'=>1,'version35'=>35,'commission_deductions36'=>['sales_agent'=>(float)$input35['sales_agent_deduction36'],'collection'=>(float)$input35['collection_deduction36'],'note'=>$input35['commission_deduction_note36']],'reference_salary35'=>$basis35['reference_salary'],'reference_allowances35'=>$basis35['reference_allowances'],'penalty35'=>round($penalty35,3),'job_title35'=>$state['job_title']??$staff['job_title'],'joining_date35'=>$state['from']??$staff['hired_on'],'working_days'=>$basis35['working_days'],'extra_days'=>$basis35['extra_days'],'extra_amount'=>$basis35['extra_amount'],'deduct_days'=>$lateDays35,'absence_deduction'=>round($absenceLoss35,3),'sick_deduction'=>round($sickLoss35,3),'friday_lateness_deduction'=>$fridayLoss35,'contract_lateness_deduction'=>$contractLoss35,'commission_source35'=>$commission35['source'],'commission_lines35'=>$commission35['lines'],'rules35'=>$rules35,'input35'=>$input35,'debt_deduction'=>$debtChoice,'debt_balance_snapshot'=>$debtBalance,'payout_on_hold'=>payout_held($staff),'department'=>$state['department']??$staff['department'],'work_company_code'=>$state['company_code']??'','residence_company_code'=>$state['residence_company_code']??'','payroll_visible'=>$visible,'allowances'=>$allowanceSnapshot['amounts'],'allowance_segments'=>$allowanceSnapshot['segments'],'allowance_deductions'=>$allowanceDeduction,'basic_deduction'=>round($basicDeduction,3),'attendance_deduction'=>$attendanceDeduction,'friday'=>$friday,'commission_items'=>$commissionItems,'payment'=>$payment,'salary'=>$monthlySalary,'salary_effective_from'=>$salarySnapshot['effective_from'],'salary_segments'=>$salarySnapshot['segments'],'salary_rule'=>$salarySnapshot['rule'],'deduction'=>round($deduction,3),'addition'=>round($addition,3),'days'=>$days,'minutes'=>$minutes,'flags'=>$flags,'settings'=>$cfg,'unpaid_excess_leave'=>$extraUnpaid,'days_detail'=>$report,'loan_items'=>$loanItems,'leave_cash_items'=>$leaveCashItems,'note'=>'تفاصيل المستحقات الشهرية؛ تعتمد قبل تجهيز تحويل البنك'];
     $net=round($monthlySalary+$addition-$deduction,3);if($net<0){$calc['flags'][]='الخصومات تتجاوز المستحق؛ راجع التسوية قبل الاعتماد.';}
 return ['calculation'=>$calc,'net'=>$net];
}
